            p = str(
                a.get("AbsolutePath")
                or a.get("SearchPath")
                or a.get("SearchDirectory")
                or ""
            ).replace("\\", "/")
            if not p:
                continue
            for fb in forbidden:
                fb_norm = fb.replace("\\", "/").rstrip("/")
                if fb_norm and (p.endswith(fb_norm) or f"/{fb_norm}" in p or p == fb_norm):
